// Abandoned-checkout capture. The checkout saves the cart + contact details
// once a shopper has typed a phone number; placing the order marks it
// recovered. Unconverted sessions get one reminder (cron) and show up in
// the merchant's "Abandoned carts" page. The token is generated by the
// browser and doubles as the secret in the recovery link.

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { query, queryOne } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";

type Ctx = { params: Promise<{ slug: string }> };

const TOKEN = z.string().regex(/^[A-Za-z0-9_-]{16,64}$/);

const SaveSchema = z.object({
  token: TOKEN,
  customerName: z.string().trim().max(120).optional().default(""),
  customerPhone: z.string().trim().min(7).max(30),
  customerEmail: z.string().trim().email().max(200).optional().or(z.literal("")),
  items: z
    .array(z.object({ productId: z.string().uuid(), quantity: z.number().int().min(1).max(999), size: z.string().max(50).optional().nullable() }))
    .min(1)
    .max(100),
});

async function storeId(slug: string) {
  return (await queryOne<{ id: string }>("SELECT id FROM stores WHERE slug = $1 AND is_active = true", [slug]))?.id ?? null;
}

export async function POST(req: NextRequest, { params }: Ctx) {
  const limited = await checkRateLimit(req, { key: "rl:checkout-session", max: 30, window: 600 });
  if (limited) return limited;

  const id = await storeId((await params).slug);
  if (!id) return NextResponse.json({ error: "Store not found" }, { status: 404 });

  const parsed = SaveSchema.safeParse(await req.json().catch(() => ({})));
  if (!parsed.success) return NextResponse.json({ error: "Invalid data" }, { status: 422 });
  const d = parsed.data;

  // Value the cart from real prices (only used for display / sorting).
  const prices = await query<{ id: string; price: number }>(
    "SELECT id, price FROM products WHERE store_id = $1 AND id = ANY($2::uuid[])",
    [id, d.items.map((i) => i.productId)]
  );
  const priceOf = new Map(prices.map((p) => [p.id, Number(p.price)]));
  const items = d.items.filter((i) => priceOf.has(i.productId));
  if (!items.length) return NextResponse.json({ ok: true });
  const subtotal = items.reduce((s, i) => s + priceOf.get(i.productId)! * i.quantity, 0);

  await query(
    `INSERT INTO checkout_sessions (store_id, token, customer_name, customer_phone, customer_email, items, subtotal)
     VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7)
     ON CONFLICT (token) DO UPDATE SET
       customer_name = EXCLUDED.customer_name, customer_phone = EXCLUDED.customer_phone,
       customer_email = EXCLUDED.customer_email, items = EXCLUDED.items,
       subtotal = EXCLUDED.subtotal, updated_at = NOW()
     WHERE checkout_sessions.store_id = EXCLUDED.store_id AND checkout_sessions.status = 'open'`,
    [id, d.token, d.customerName || null, d.customerPhone, d.customerEmail || null, JSON.stringify(items), subtotal]
  );
  return NextResponse.json({ ok: true });
}

/** Restore a cart from a recovery link (?token=…). */
export async function GET(req: NextRequest, { params }: Ctx) {
  const limited = await checkRateLimit(req, { key: "rl:checkout-session-get", max: 30, window: 600 });
  if (limited) return limited;

  const token = TOKEN.safeParse(req.nextUrl.searchParams.get("token"));
  if (!token.success) return NextResponse.json({ error: "Invalid link" }, { status: 400 });
  const id = await storeId((await params).slug);
  if (!id) return NextResponse.json({ error: "Store not found" }, { status: 404 });

  const session = await queryOne<{
    customer_name: string | null; customer_phone: string; customer_email: string | null;
    items: { productId: string; quantity: number; size?: string | null }[];
  }>(
    "SELECT customer_name, customer_phone, customer_email, items FROM checkout_sessions WHERE store_id = $1 AND token = $2 AND status = 'open'",
    [id, token.data]
  );
  if (!session) return NextResponse.json({ error: "This cart has expired or was already ordered" }, { status: 404 });

  const products = await query<{ id: string; name: string; price: number; image_url: string | null; images: string[] | null; stock_quantity: number }>(
    "SELECT id, name, price, image_url, images, stock_quantity FROM products WHERE store_id = $1 AND is_active = true AND id = ANY($2::uuid[])",
    [id, session.items.map((i) => i.productId)]
  );
  const byId = new Map(products.map((p) => [p.id, p]));

  return NextResponse.json({
    customerName: session.customer_name ?? "",
    customerPhone: session.customer_phone,
    customerEmail: session.customer_email ?? "",
    items: session.items
      .filter((i) => byId.has(i.productId) && byId.get(i.productId)!.stock_quantity > 0)
      .map((i) => {
        const p = byId.get(i.productId)!;
        return {
          product_id: p.id,
          name: p.name,
          price: Number(p.price),
          image_url: p.image_url ?? p.images?.[0] ?? undefined,
          stock_quantity: p.stock_quantity,
          quantity: Math.min(i.quantity, p.stock_quantity),
          size: i.size ?? null,
        };
      }),
  });
}
